mapper.select:
select c.category_id, c.category_name, c.order_num, c.status, c.del_flag, c.create_by, c.create_time, c.update_by, c.update_time, c.remark, (select count(1) from shop_product p where p.category_id = c.category_id and p.del_flag = '0') as product_count from shop_category c
c.del_flag = '0' and c.category_name like concat('%', #{categoryName}, '%') and c.status = #{status}
order by c.order_num, c.category_id

mapper.update:
update shop_category
category_name = #{categoryName}, order_num = #{orderNum}, status = #{status}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where category_id = #{categoryId}
